  }
  /// Gets individual value stored with [key], if any.
  @objc func getValue(
    key: NSString, options: SharedPreferencesPigeonOptionsBridge, wrappedError: PigeonError
  ) -> NSObject? {
    do {
      return try _PigeonFfiCodec.writeValue(
        value: api!.getValue(key: key as String, options: options.toSwift()), isObject: true)
        as? NSObject
    } catch let error as PigeonError {
      wrappedError.code = error.code
      wrappedError.message = error.message
      wrappedError.details = error.details
    } catch let error {
      wrappedError.code = "\(error)"
      wrappedError.message = "\(type(of: error))"
      wrappedError.details = "Stacktrace: \(Thread.callStackSymbols)"
    }
    return nil
  }
  /// Gets all properties from shared preferences data set with matching prefix.
  @objc func getKeys(
    allowList: [NSObject]?, options: SharedPreferencesPigeonOptionsBridge, wrappedError: PigeonError
  ) -> [NSObject]? {
    do {
      return try _PigeonFfiCodec.writeValue(
        value: api!.getKeys(
          allowList: _PigeonFfiCodec.readValue(value: allowList as NSObject?, type: "String")
            as? [String], options: options.toSwift())) as? [NSObject]
    } catch let error as PigeonError {
      wrappedError.code = error.code
      wrappedError.message = error.message
      wrappedError.details = error.details
    } catch let error {
      wrappedError.code = "\(error)"
      wrappedError.message = "\(type(of: error))"
      wrappedError.details = "Stacktrace: \(Thread.callStackSymbols)"
    }
    return nil
  }
}
